function getRaiderHistory(){try{return JSON.parse(localStorage.getItem(raiderHistoryKey())||'{}')}catch{return{}}}
function recordRaiderResult(index,seconds,miss=false){const history=getRaiderHistory(),key=String(droneGlobalPosition(index)),entry=history[key]||{average:0,samples:0,misses:0};if(Number.isFinite(seconds)){entry.average=(entry.average*entry.samples+seconds)/(entry.samples+1);entry.samples++}if(miss)entry.misses++;history[key]=entry;try{localStorage.setItem(raiderHistoryKey(),JSON.stringify(history))}catch{}}
function chooseEliteRaiders(count=2){const history=getRaiderHistory(),candidates=Array.from({length:13},(_,index)=>{const entry=history[String(droneGlobalPosition(index))];return {index,score:entry?.samples?entry.average+(entry.misses||0)*4:null}}),known=candidates.filter(card=>card.score!==null).sort((a,b)=>b.score-a.score),selected=shuffle(known.slice(0,Math.min(3,known.length)).map(card=>card.index)).slice(0,count),remaining=shuffle(candidates.map(card=>card.index).filter(index=>!selected.includes(index)));return [...selected,...remaining].slice(0,count)}
