function readCustomStacks(){try{const stacks=JSON.parse(localStorage.getItem(CUSTOM_STACKS_KEY)||'[]');return Array.isArray(stacks)?stacks.filter(stack=>stack?.id&&stack?.name&&Array.isArray(stack.cards)&&stack.cards.length===52):[]}catch{return[]}}
