function addCustomCard(suit){if(!customDraft.selectedRank)return;const card=[customDraft.selectedRank,suit];if(customEditingIndex!==null){const otherIndex=customDraft.cards.findIndex(existing=>cardKey(existing)===cardKey(card)),oldCard=customDraft.cards[customEditingIndex];customDraft.cards[customEditingIndex]=card;if(otherIndex>=0&&otherIndex!==customEditingIndex)customDraft.cards[otherIndex]=oldCard;customEditingIndex=null;customDraft.selectedRank=null;saveCustomDraft();renderCustomBuilder();sound('build');return}if(customDraft.cards.length>=52||customDraft.cards.some(existing=>cardKey(existing)===cardKey(card)))return;customDraft.cards.push(card);customDraft.selectedRank=null;saveCustomDraft();renderCustomBuilder();sound('build')}
function saveCompletedCustomStack(){if(customDraft.cards.length!==52)return;const name=$('customStackName').value.trim().replace(/\s+/g,' ').replace(/[<>]/g,'');if(!name){$('customStackName').focus();return}const stacks=readCustomStacks(),existingIndex=stacks.findIndex(stack=>stack.id===customEditingStackId),id=customEditingStackId||`custom-${Date.now().toString(36)}`,saved={id,name:name.toUpperCase(),cards:customDraft.cards.map(card=>[...card]),createdAt:existingIndex>=0?stacks[existingIndex].createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(existingIndex>=0)stacks[existingIndex]=saved;else stacks.push(saved);STACKS[id]={name:saved.name,cards:saved.cards,custom:true};try{localStorage.setItem(CUSTOM_STACKS_KEY,JSON.stringify(stacks));localStorage.removeItem(CUSTOM_DRAFT_KEY)}catch{}customDraft={cards:[],selectedRank:null};customEditingStackId=null;$('customStackName').value='';$('saveCustomStack').textContent='SAVE VERIFIED STACK';$('customStackBuilder').classList.add('hidden');$('stackChooser').classList.remove('hidden');renderStackOptions();sound('victory')}

