function noise(duration=.14,volume=.07,delay=0){if($('soundButton').dataset.muted==='true')return;try{const ctx=tone.ctx||(tone.ctx=new AudioContext()),start=ctx.currentTime+delay,buffer=ctx.createBuffer(1,ctx.sampleRate*duration,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const source=ctx.createBufferSource(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=900;gain.gain.setValueAtTime(volume,start);gain.gain.exponentialRampToValueAtTime(.001,start+duration);source.connect(filter).connect(gain).connect(ctx.destination);source.start(start)}catch{}}
function sound(name){if(name==='select'){tone(330,.045,.018,'sine')}else if(name==='laser'){tone(1050,.13,.032,'sawtooth',0,240);tone(1450,.08,.018,'square',0,500)}else if(name==='enemyLaser'){tone(680,.18,.04,'square',0,140);tone(430,.2,.025,'sawtooth',0,90)}else if(name==='groundLaser'){tone(190,.16,.035,'sine',0,740);tone(1250,.28,.045,'sawtooth',.1,260)}else if(name==='droneBlast'){noise(.3,.09);tone(130,.3,.055,'square',0,38)}else if(name==='impact'){tone(150,.12,.045,'square',0,55)}else if(name==='burn'){noise(.34,.025);tone(92,.32,.018,'sawtooth',0,52)}else if(name==='build'){tone(440,.08);tone(660,.12,.04,'sine',.07)}else if(name==='deploy'){tone(108,2.5,.022,'sawtooth',1,84);tone(216,2.5,.008,'square',1,168)}else if(name==='intercept'){tone(720,.07,.04,'square');tone(1080,.13,.04,'sine',.06)}else if(name==='eliteAlarm'){[0,.55,1.1].forEach(delay=>{tone(790,.34,.045,'square',delay,420);tone(395,.34,.025,'sawtooth',delay,210)})}else if(name==='error'){tone(170,.12,.04,'sawtooth',0,95)}else if(name==='breach'){tone(120,.28,.06,'sawtooth',0,35)}else if(name==='victory'){[523,659,784,1047].forEach((f,i)=>tone(f,.22,.04,'sine',i*.11))}else if(name==='pop'){noise(.1,.05);tone(180,.1,.025,'square',0,55)}else if(name==='highscore'){noise(.28,.09);noise(.22,.08,.18);[392,523,659,784,1047].forEach((f,i)=>tone(f,.3,.045,'sine',i*.1))}}

$('restartButton').onclick=restart;$('pauseButton').onclick=()=>{state.paused=!state.paused;updateUI()};$('soundButton').onclick=e=>{const muted=e.currentTarget.dataset.muted!=='true';e.currentTarget.dataset.muted=muted;e.currentTarget.textContent=muted?'MUTE':'◖))'};
$('tutorialNext').onclick=()=>{const finalStep=state.tutorialStep===activeTutorialSlides().length-1;if(finalStep)finishTutorial();else{state.tutorialStep++;renderTutorialStep()}};window.addEventListener('resize',()=>{if(!$('tutorial').classList.contains('hidden'))renderTutorialStep()});
$('ship').addEventListener('animationiteration',event=>{if(event.animationName==='saucer-bank-patrol'&&state.phase===1)randomizeShipFlight()});randomizeShipFlight();
$('createCustomStack').onclick=openCustomBuilder;$('undoCustomCard').onclick=()=>{if(!customDraft.cards.length)return;customDraft.cards.pop();customDraft.selectedRank=null;saveCustomDraft();renderCustomBuilder();sound('select')};$('exitCustomBuilder').onclick=()=>{saveCustomDraft();$('customStackBuilder').classList.add('hidden');$('stackChooser').classList.remove('hidden');sound('select')};$('returnToCustomEntry').onclick=()=>{customEditingIndex=51;customDraft.selectedRank=customDraft.cards[51][0];renderCustomBuilder();sound('select')};$('saveCustomStack').onclick=saveCompletedCustomStack;$('customStackName').addEventListener('keydown',event=>{if(event.key==='Enter')saveCompletedCustomStack()});registerCustomStacks();renderStackOptions();
document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{state.mode=button.dataset.mode;state.forceTutorial=$('showTutorialToggle').checked;state.positionOrder=state.mode==='super'?shuffle(Array.from({length:52},(_,i)=>i)):Array.from({length:52},(_,i)=>i);state.dronePositionOrder=state.mode==='super'?makeDroneOrder(state.positionOrder):[...state.positionOrder];$('modeChooser').classList.add('hidden');state.sector=0;state.phase=1;state.paused=false;state.ending=false;state.built=0;state.baysBuilt=true;state.turretsDeployed=false;state.score=0;state.sectorStartScore=0;state.damagePenalty=0;state.droneDestroyed=0;state.health=Array(13).fill(0);resetMothership();renderFortress();renderControls();updateUI();if(hasCompletedTutorial()&&!state.forceTutorial)beginMission();else startTutorial();sound('build')});
renderFortress();renderControls();updateUI();
